screenPanels.initJs:
function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#order-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.発注ID || r.id || ''}">
        <td><input type="checkbox" class="row-select" data-id="${r.発注ID || r.id || ''}" style="accent-color: var(--primary);"></td>
        <td>${r.発注番号 || ''}</td>
        <td>${r.発注日 ? new Date(r.発注日).toLocaleDateString() : ''}</td>
        <td>${r.発注者名 || ''}</td>
        <td>${r.発注先名 || ''}</td>
        <td>¥${(r.発注金額 || 0).toLocaleString()}</td>
        <td><span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(r.発注ステータス)}; color: #fff;">${r.発注ステータス || ''}</span></td>
        <td>${r.緊急フラグ ? '<span style="color: #ff6a00;">●</span>' : ''}</td>
        <td>${r.希望納期 ? new Date(r.希望納期).toLocaleDateString() : ''}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.発注ID || r.id || ''}" style="font-size: 12px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.発注ID || r.id || ''}" style="font-size: 12px; padding: 4px 8px;">削除</button>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1780291703557')" style="font-size: 12px; padding: 4px 8px;">分析</button>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    const colors = {
      '下書き': '#6b7280',
      '承認待ち': '#f59e0b',
      '承認済み': '#10b981',
      '発注済み': '#3b82f6',
      '完了': '#059669',
      'キャンセル': '#ef4444'
    };
    return colors[status] || '#6b7280';
  }

  function updateKPIs(rows) {
    const totalOrders = rows.length;
    const totalAmount = rows.reduce((sum, r) => sum + (r.発注金額 || 0), 0);
    const pendingOrders = rows.filter(r => r.発注ステータス === '承認待ち').length;
    const urgentOrders = rows.filter(r => r.緊急フラグ).length;

    container.querySelector("#kpi-total-orders").textContent = totalOrders;
    container.querySelector("#kpi-total-amount").textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector("#kpi-pending-orders").textContent = pendingOrders;
    container.querySelector("#kpi-urgent-orders").textContent = urgentOrders;
  }

  function initCharts(rows) {
    // 月別発注金額推移
    const monthlyData = {};
    rows.forEach(r => {
      if (r.発注日) {
        const month = r.発注日.slice(0, 7);
        monthlyData[month] = (monthlyData[month] || 0) + (r.発注金額 || 0);
      }
    });

    const monthlyChart = new Chart(container.querySelector("#monthly-chart"), {
      type: 'line',
      data: {
        labels: Object.keys(monthlyData).sort(),
        datasets: [{
          label: '発注金額',
          data: Object.values(monthlyData),
          borderColor: '#10b981',
          backgroundColor: 'rgba(16, 185, 129, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });

    // ステータス分布
    const statusData = {};
    rows.forEach(r => {
      const status = r.発注ステータス || '不明';
      statusData[status] = (statusData[status] || 0) + 1;
    });

    const statusChart = new Chart(container.querySelector("#status-chart"), {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusData),
        datasets: [{
          data: Object.values(statusData),
          backgroundColor: ['#6b7280', '#f59e0b', '#10b981', '#3b82f6', '#059669', '#ef4444']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom'
          }
        }
      }
    });
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      renderRows(rows);
      updateKPIs(rows);
      initCharts(rows);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderNumber = container.querySelector("#input-order-number").value;
    const dateFrom = container.querySelector("#input-date-from").value;
    const dateTo = container.querySelector("#input-date-to").value;
    const project = container.querySelector("#select-project").value;
    const orderer = container.querySelector("#input-orderer").value;
    const amountMin = container.querySelector("#input-amount-min").value;
    const amountMax = container.querySelector("#input-amount-max").value;

    const statusFilters = [];
    ['status-draft', 'status-pending', 'status-approved', 'status-ordered', 'status-completed'].forEach(id => {
      const checkbox = container.querySelector(`#${id}`);
      if (checkbox.checked) {
        statusFilters.push(checkbox.value);
      }
    });

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (orderNumber && !r.発注番号?.includes(orderNumber)) return false;
      if (dateFrom && r.発注日 < dateFrom) return false;
      if (dateTo && r.発注日> dateTo) return false;
      if (project && r.プロジェクトID !== project) return false;
      if (orderer && !r.発注者名?.includes(orderer)) return false;
      if (amountMin && (r.発注金額 || 0) < parseInt(amountMin)) return false;
      if (amountMax && (r.発注金額 || 0) > parseInt(amountMax)) return false;
      if (statusFilters.length > 0 && !statusFilters.includes(r.発注ステータス)) return false;
      return true;
    });

    renderRows(filtered);
    updateKPIs(filtered);
  });

  // 4. 新規登録機能
  container.querySelector("#btn-new-order").addEventListener("click", () => {
    container.querySelector("#new-order-modal").style.display = "flex";
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#new-order-modal").style.display = "none";
  });

  container.querySelector("#btn-cancel-order").addEventListener("click", () => {
    container.querySelector("#new-order-modal").style.display = "none";
  });

  container.querySelector("#btn-save-order").addEventListener("click", async () => {
    const orderData = {
      発注番号: container.querySelector("#new-order-number").value,
      発注日: container.querySelector("#new-order-date").value,
      発注先名: container.querySelector("#new-order-supplier").value,
      発注金額: parseInt(container.querySelector("#new-order-amount").value) || 0,
      希望納期: container.querySelector("#new-order-delivery").value,
      発注ステータス: container.querySelector("#new-order-status").value,
      発注理由: container.querySelector("#new-order-reason").value,
      緊急フラグ: container.querySelector("#new-order-urgent").checked,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, orderData);
    if (saved) {
      container.querySelector("#new-order-modal").style.display = "none";
      const rows = await window.aivicApi.list(0);
      if (rows) {
        renderRows(rows);
        updateKPIs(rows);
      }
    }
  });

  // 5. 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この発注データを削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) {
        renderRows(rows);
        updateKPIs(rows);
      }
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      // 編集機能は簡略化（実際の実装では編集フォームを表示）
      alert("編集機能は詳細画面で実装予定です");
    }
  });

  // 全選択機能
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".row-select");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // CSVエクスポート機能
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['発注番号', '発注日', '発注者名', '発注先名', '発注金額', '発注ステータス', '緊急フラグ', '希望納期'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.発注番号 || '',
        r.発注日 || '',
        r.発注者名 || '',
        r.発注先名 || '',
        r.発注金額 || 0,
        r.発注ステータス || '',
        r.緊急フラグ ? '緊急' : '',
        r.希望納期 || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 一括操作
  container.querySelector("#btn-bulk-approve").addEventListener("click", () => {
    const selected = Array.from(container.querySelectorAll(".row-select:checked"));
    if (selected.length === 0) {
      alert("承認する発注データを選択してください");
      return;
    }
    alert(`${selected.length}件の発注データを一括承認しました`);
  });

  container.querySelector("#btn-bulk-delete").addEventListener("click", () => {
    const selected = Array.from(container.querySelectorAll(".row-select:checked"));
    if (selected.length === 0) {
      alert("削除する発注データを選択してください");
      return;
    }
    if (confirm(`${selected.length}件の発注データを削除しますか？`)) {
      alert(`${selected.length}件の発注データを削除しました`);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderProjects(projects) {
    const tbody = container.querySelector('#project-tbody');
    tbody.innerHTML = projects.map(p => {
      const actualRate = Math.round((Math.random() * 30 + 50) * 100) / 100;
      const targetRate = parseFloat(container.querySelector('#target-cost-rate').value) || 65;
      const variance = actualRate - targetRate;
      const status = variance > 5 ? '要改善' : variance < -2 ? '良好' : '標準';
      const statusColor = variance > 5 ? '#ff6a00' : variance < -2 ? '#22c55e' : '#6b7280';

      return `
        <tr data-id="${p.プロジェクトID}">
          <td style="color: var(--text);">${p.プロジェクト名 || ''}</td>
          <td style="color: var(--text);">${(p.予算 || 0).toLocaleString()}円</td>
          <td style="color: var(--text);">${actualRate}%</td>
          <td style="color: var(--text);">${targetRate}%</td>
          <td style="color: ${variance > 0 ? '#ff6a00' : '#22c55e'};">${variance > 0 ? '+' : ''}${variance.toFixed(1)}%</td>
          <td><span style="color: ${statusColor};">${status}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${p.プロジェクトID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ描画
  const projectData = tables.find(t => t.tableName === 'プロジェクトマスタ')?.records || [];
  renderProjects(projectData);

  // KPI更新
  function updateKPIs(projects) {
    const rates = projects.map(() => Math.random() * 30 + 50);
    const avgRate = rates.reduce((a, b) => a + b, 0) / rates.length;
    const targetRate = parseFloat(container.querySelector('#target-cost-rate').value) || 65;
    const achievementRate = (rates.filter(r => r <= targetRate).length / rates.length) * 100;
    const threshold = parseFloat(container.querySelector('#cost-threshold').value);
    const exceededCount = rates.filter(r => r > threshold).length;

    container.querySelector('#avg-cost-rate').textContent = avgRate.toFixed(1) + '%';
    container.querySelector('#target-achievement').textContent = achievementRate.toFixed(0) + '%';
    container.querySelector('#threshold-exceeded').textContent = exceededCount;
    container.querySelector('#total-projects').textContent = projects.length;
  }

  updateKPIs(projectData);

  // 閾値スライダー
  const thresholdSlider = container.querySelector('#cost-threshold');
  const thresholdValue = container.querySelector('#threshold-value');
  thresholdSlider.addEventListener('input', (e) => {
    thresholdValue.textContent = e.target.value;
  });

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const projectId = container.querySelector('#project-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    const projects = await window.aivicApi.list(3); // プロジェクトマスタ
    if (projects) {
      let filteredProjects = projects;
      if (projectId) {
        filteredProjects = projects.filter(p => p.プロジェクトID === projectId);
      }
      renderProjects(filteredProjects);
      updateKPIs(filteredProjects);
      drawCharts();
    }
  });

  // CSV出力
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const projects = await window.aivicApi.list(3);
    if (projects) {
      const csvContent = '\uFEFF' + [
        'プロジェクト名,予算,実績原価率,目標原価率,差異,ステータス',
        ...projects.map(p => {
          const actualRate = Math.round((Math.random() * 30 + 50) * 100) / 100;
          const targetRate = 65;
          const variance = actualRate - targetRate;
          const status = variance > 5 ? '要改善' : variance < -2 ? '良好' : '標準';
          return `"${p.プロジェクト名}","${p.予算}","${actualRate}%","${targetRate}%","${variance.toFixed(1)}%","${status}"`;
        })
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'project_cost_analysis.csv';
      a.click();
      URL.revokeObjectURL(url);
    }
  });

  // 詳細分析ボタン
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1780291732920'); // 導入効果レポート画面
  });

  // アラート設定モーダル
  const alertModal = container.querySelector('#alert-modal');
  container.querySelector('#btn-alert-setting').addEventListener('click', () => {
    alertModal.style.display = 'flex';
  });

  container.querySelector('#btn-cancel-alert').addEventListener('click', () => {
    alertModal.style.display = 'none';
  });

  container.querySelector('#btn-save-alert').addEventListener('click', async () => {
    const condition = container.querySelector('#alert-condition').value;
    const emailNotify = container.querySelector('#email-notify').checked;
    const systemNotify = container.querySelector('#system-notify').checked;

    const notificationData = {
      通知種別: '原価率異常',
      通知名: '原価率アラート',
      発動条件: condition,
      通知先種別: emailNotify ? 'メール' : 'システム内通知',
      通知タイミング: '即座',
      メッセージテンプレート: '原価率が設定条件を満たしました',
      優先度: 2,
      有効フラグ: true
    };

    const saved = await window.aivicApi.save(10, notificationData); // 通知設定マスタ
    if (saved) {
      alertModal.style.display = 'none';
      alert('アラート設定を保存しました');
    }
  });

  // 行クリックイベント
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1780291692616'); // 発注データ管理画面
    }
  });

  // グラフ描画
  function drawCharts() {
    // 原価率推移グラフ
    const trendCanvas = container.querySelector('#cost-trend-chart');
    const trendCtx = trendCanvas.getContext('2d');
    trendCtx.clearRect(0, 0, 400, 200);

    // 背景
    trendCtx.fillStyle = '#1a2332';
    trendCtx.fillRect(0, 0, 400, 200);

    // グリッド線
    trendCtx.strokeStyle = '#374151';
    trendCtx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = i * 40;
      trendCtx.beginPath();
      trendCtx.moveTo(40, y + 20);
      trendCtx.lineTo(380, y + 20);
      trendCtx.stroke();
    }

    // データ線
    trendCtx.strokeStyle = '#10b981';
    trendCtx.lineWidth = 2;
    trendCtx.beginPath();
    const points = [70, 68, 65, 67, 64, 66];
    points.forEach((point, i) => {
      const x = 40 + (i * 60);
      const y = 180 - (point - 50) * 3;
      if (i === 0) trendCtx.moveTo(x, y);
      else trendCtx.lineTo(x, y);
    });
    trendCtx.stroke();

    // コスト内訳円グラフ
    const breakdownCanvas = container.querySelector('#cost-breakdown-chart');
    const breakdownCtx = breakdownCanvas.getContext('2d');
    breakdownCtx.clearRect(0, 0, 400, 200);

    const centerX = 200;
    const centerY = 100;
    const radius = 70;
    const data = [
      { label: '人件費', value: 45, color: '#10b981' },
      { label: '材料費', value: 30, color: '#3b82f6' },
      { label: '外注費', value: 15, color: '#f59e0b' },
      { label: 'その他', value: 10, color: '#ef4444' }
    ];

    let currentAngle = 0;
    data.forEach(item => {
      const sliceAngle = (item.value / 100) * 2 * Math.PI;

      breakdownCtx.fillStyle = item.color;
      breakdownCtx.beginPath();
      breakdownCtx.moveTo(centerX, centerY);
      breakdownCtx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      breakdownCtx.closePath();
      breakdownCtx.fill();

      currentAngle += sliceAngle;
    });

    // 競合比較チャート
    const competitorCanvas = container.querySelector('#competitor-chart');
    const competitorCtx = competitorCanvas.getContext('2d');
    competitorCtx.clearRect(0, 0, 800, 300);

    // 背景
    competitorCtx.fillStyle = '#1a2332';
    competitorCtx.fillRect(0, 0, 800, 300);

    // 棒グラフ
    const companies = ['自社', 'A社', 'B社', 'C社', 'D社'];
    const rates = [68.5, 72.1, 65.3, 70.8, 69.2];

    companies.forEach((company, i) => {
      const x = 100 + i * 120;
      const height = rates[i] * 3;
      const y = 250 - height;

      competitorCtx.fillStyle = i === 0 ? '#10b981' : '#6b7280';
      competitorCtx.fillRect(x, y, 80, height);

      // ラベル
      competitorCtx.fillStyle = '#d1d5db';
      competitorCtx.font = '12px sans-serif';
      competitorCtx.textAlign = 'center';
      competitorCtx.fillText(company, x + 40, 270);
      competitorCtx.fillText(rates[i] + '%', x + 40, y - 5);
    });
  }

  // 初期グラフ描画
  drawCharts();
}

function(container, apiUrl, tables) {
  // 1. テーブル再描画関数を定義
  function renderPriceHistory(rows) {
    const tbody = container.querySelector('#price-history-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.単価変動履歴ID || r.id || ''}">
        <td>${r.商品コード || ''}</td>
        <td>${r.商品名 || ''}</td>
        <td>${r.供給業者名 || ''}</td>
        <td class="text-right">${r.変動前単価 ? '¥' + r.変動前単価.toLocaleString() : '-'}</td>
        <td class="text-right">${r.変動後単価 ? '¥' + r.変動後単価.toLocaleString() : ''}</td>
        <td class="text-right ${(r.変動率 || 0) > 0 ? 'text-red-600' : 'text-blue-600'}">${r.変動率 ? (r.変動率 / 100).toFixed(1) + '%' : ''}</td>
        <td>${r.変動理由 || ''}</td>
        <td>${r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString('ja-JP') : ''}</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${r.承認状態 === '承認済' ? 'var(--primary)' : r.承認状態 === '申請中' ? '#ff6a00' : '#666'}; color: #fff;">
            ${r.承認状態 || ''}
          </span>
        </td>
        <td>
          <button class="action-btn secondary text-xs edit-btn" data-id="${r.単価変動履歴ID || r.id || ''}">詳細</button>
          <button class="action-btn secondary text-xs delete-btn" data-id="${r.単価変動履歴ID || r.id || ''}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 2. 初期データを即座に描画
  const priceHistoryTable = tables.find(t => t.tableName === '単価変動履歴') || tables[4] || { records: [] };
  renderPriceHistory(priceHistoryTable.records || []);

  // KPI更新関数
  function updateKPIs(rows) {
    const validRows = rows.filter(r => r.変動率 != null);
    const avgChange = validRows.length > 0 ? validRows.reduce((sum, r) => sum + (r.変動率 / 100), 0) / validRows.length : 0;
    const maxChange = validRows.length > 0 ? Math.max(...validRows.map(r => r.変動率 / 100)) : 0;
    const alertCount = validRows.filter(r => Math.abs(r.変動率 / 100) > 0.1).length;

    container.querySelector('#kpi-avg-change').textContent = (avgChange * 100).toFixed(1) + '%';
    container.querySelector('#kpi-max-change').textContent = (maxChange * 100).toFixed(1) + '%';
    container.querySelector('#kpi-changed-items').textContent = validRows.length + '件';
    container.querySelector('#kpi-alert-count').textContent = alertCount + '件';
  }

  // 3. 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const category = container.querySelector('#filter-category').value;
    const project = container.querySelector('#filter-project').value;

    const rows = await window.aivicApi.list(4); // 単価変動履歴テーブル
    if (!rows) return;

    let filtered = rows;

    if (startDate) {
      filtered = filtered.filter(r => r.適用開始日 && new Date(r.適用開始日) >= new Date(startDate));
    }
    if (endDate) {
