    timeCtx.strokeStyle = "#e9ecef";
    timeCtx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = (200 / 5) * i;
      timeCtx.beginPath();
      timeCtx.moveTo(40, y);
      timeCtx.lineTo(380, y);
      timeCtx.stroke();
    }

    // データライン（導入前）
    timeCtx.strokeStyle = "#dc3545";
    timeCtx.lineWidth = 2;
    timeCtx.beginPath();
    const beforeData = [180, 175, 170, 165, 160, 155];
    beforeData.forEach((val, i) => {
      const x = 40 + (340 / 5) * i;
      const y = 200 - (val / 200 * 180);
      if (i === 0) timeCtx.moveTo(x, y);
      else timeCtx.lineTo(x, y);
    });
    timeCtx.stroke();

    // データライン（導入後）
    timeCtx.strokeStyle = "#28a745";
    timeCtx.lineWidth = 2;
    timeCtx.beginPath();
    const afterData = [120, 110, 105, 95, 90, 85];
    afterData.forEach((val, i) => {
      const x = 40 + (340 / 5) * i;
      const y = 200 - (val / 200 * 180);
