    const endDate = report.対象期間終了日 ? new Date(report.対象期間終了日).toLocaleDateString('ja-JP') : '';
    container.querySelector('#detail-target-period').textContent = startDate && endDate ? `${startDate} ～ ${endDate}` : '-';

    container.querySelector('#detail-process-time').textContent = report.処理時間秒 ? `${report.処理時間秒}秒` : '-';
    container.querySelector('#detail-file-size').textContent = formatFileSize(report.ファイルサイズ);
    container.querySelector('#detail-download-count').textContent = `${report.ダウンロード回数 || 0}回`;

    // エラーメッセージの表示制御
    const errorSection = container.querySelector('#error-section');
    if (report.生成ステータス === 'エラー' && report.エラーメッセージ) {
      container.querySelector('#detail-error-message').textContent = report.エラーメッセージ;
      errorSection.style.display = 'block';
    } else {
      errorSection.style.display = 'none';
    }

    // ダウンロードボタンの有効/無効制御
    const downloadBtn = container.querySelector('#download-report');
    downloadBtn.disabled = report.生成ステータス !== '完了';
    if (downloadBtn.disabled) {
      downloadBtn.style.opacity = '0.5';
      downloadBtn.style.cursor = 'not-allowed';
    } else {
      downloadBtn.style.opacity = '1';
      downloadBtn.style.cursor = 'pointer';
    }

    container.querySelector('#report-detail-modal').style.display = 'flex';
  }

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#report-detail-modal').style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#report-detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#report-detail-modal')) {
      container.querySelector('#report-detail-modal').style.display = 'none';
    }
  });

  // ダウンロード機能
  container.querySelector('#download-report').addEventListener('click', async () => {
    if (!selectedReportId) return;

    try {
      const report = currentReports.find(r => (r.レポート生成履歴ID || r.id) === selectedReportId);
      if (report && report.生成ステータス === '完了') {
        // ダウンロード回数を更新
        const updatedReport = await window.aivicApi.update(0, selectedReportId, {
          ダウンロード回数: (report.ダウンロード回数 || 0) + 1,
          最終ダウンロード日時: new Date().toISOString()
        });

        if (updatedReport) {
          // 実際のファイルダウンロード処理（模擬）
          alert(`レポート「${report.レポート名}」をダウンロードしました`);

          // 一覧を更新
          const refreshedRows = await window.aivicApi.list(0);
          if (refreshedRows) {
            currentReports = refreshedRows;
            renderRows(refreshedRows);
          }

          container.querySelector('#report-detail-modal').style.display = 'none';
        }
      }
    } catch (error) {
      console.error('ダウンロードエラー:', error);
      alert('ダウンロードに失敗しました');
    }
  });

  // 削除機能
  container.querySelector('#delete-report').addEventListener('click', async () => {
    if (!selectedReportId) return;

    if (!confirm('このレポートを削除しますか？')) return;

    try {
      await window.aivicApi.delete(0, selectedReportId);

      // 一覧を更新
      const refreshedRows = await window.aivicApi.list(0);
      if (refreshedRows) {
        currentReports = refreshedRows;
        renderRows(refreshedRows);
      }

      container.querySelector('#report-detail-modal').style.display = 'none';
      alert('レポートを削除しました');
    } catch (error) {
      console.error('削除エラー:', error);
      alert('削除に失敗しました');
    }
  });
}
